  [20553] = { nil, "与える物理ダメージが$N1増加しています。\n攻撃速度が$N2%上昇しています。", nil, 0xbc6c8e1d, "mu" },
  [20554] = { "$D1の間、呪文の詠唱速度と攻撃速度を$N1%上昇させます。", "詠唱速度と攻撃速度が$N1%上昇しています。", 0x6170a182, 0x381e0def, "uu" },
