  [20919] = { "パラディンに、通常の武器ダメージの$N1%に等しい追加Holyダメージを与える機会を与えます。パラディンに同時に有効にできるSealは1つだけです。効果時間は$D1です。\n\nこのSealの力を解き放つと敵を裁き、即座に$N3のHolyダメージを与えます。対象がスタンまたは行動不能状態の場合は$N4のHolyダメージを与えます。", "近接攻撃に、追加のHolyダメージを与える可能性があります。", 0xf5147b64, 0x256a386d, "uu" },
  [20920] = { "パラディンに、通常の武器ダメージの$N1%に等しい追加Holyダメージを与える機会を与えます。パラディンに同時に有効にできるSealは1つだけです。効果時間は$D1です。\n\nこのSealの力を解き放つと敵を裁き、即座に$N3のHolyダメージを与えます。対象がスタンまたは行動不能状態の場合は$N4のHolyダメージを与えます。", "近接攻撃に、追加のHolyダメージを与える可能性があります。", 0xdb50e8a6, 0x256a386d, "uu" },
